            if ident in present:
                present.remove(ident)
        elif op == 'begin':
            open_txn = True
            saved = (set(present), high)
        elif op == 'commit':
            open_txn = False
            saved = None
        elif op == 'rollback':
            open_txn = False
            if saved is not None:
                present, high = saved
                saved = None
